      guideAlphaCannotTell: "Alpha cannot diagnose any disease, intelligence, emotional state, or personality. Reduced alpha can simply be due to eyes being open, anxiety, or attention.",
    guideAlphaDesc: "Alpha waves are the most common rhythmic activity in EEG, prominent when a person closes their eyes in a relaxed but awake state. It is one of the most classic findings in EEG research.",
    guideAlphaPattern: "Typical alpha rhythm appears sinusoidal, most prominent in occipital leads (e.g. O1, O2), showing regular ~10 Hz oscillations on EEG.",
    guideAlphaTitle: "Alpha Waves (α)",
    guideAlphaWhat: "α waves have a frequency of 8–13 Hz, amplitude of 20–100 μV, mainly distributed in the occipital lobe. They quickly attenuate upon opening eyes, known as alpha blockade.",
    guideAlphaWhy: "Alpha is an important indicator of cortical 'idling' state. Absence or abnormality of alpha may suggest cortical dysfunction, but alpha alone cannot diagnose any disease.",
    guideArtifactsCannotTell: "Artifact removal cannot eliminate all noise, nor perfectly restore contaminated brain components. Over-removal may lose genuine EEG signal.",
    guideArtifactsDesc: "Artifacts are non-cerebral signals in EEG recordings that can severely impact analysis if not identified and removed.",
    guideArtifactsTitle: "EEG Artifacts",
    guideArtifactsWhat: "Common artifacts: eye blinks (EOG, up to 200 μV), muscle activity (EMG, >20 Hz), power line interference (50/60 Hz), electrode movement, sweat. Each has distinctive waveform and frequency features.",
    guideArtifactsWhy: "Artifact identification is the first step in EEG analysis. Without handling artifacts, frequency analysis, connectivity, and all subsequent analyses may produce erroneous conclusions. ICA is the most common automated removal method.",
    guideBandpowerCannotTell: "Bandpower cannot be used to diagnose any disease. There is large inter-individual variability (age, sex, genetics, state), and no absolute 'normal' value.",
    guideBandpowerDesc: "Bandpower summarizes PSD results into meaningful band values, one of the most common EEG metrics.",
    guideBandpowerTitle: "Bandpower",
    guideBandpowerWhat: "Extract energy per band from PSD: delta (0.5–4 Hz), theta (4–8 Hz), alpha (8–13 Hz), beta (13–30 Hz). Expressed as absolute power (μV²) or relative power (%).",
    guideBandpowerWhy: "Bandpower underpins EEG biomarker research. E.g., alpha/theta ratio assesses relaxation, theta/beta ratio has been studied as a candidate ADHD marker (but not approved for clinical diagnosis).",
    guideBetaCannotTell: "Beta cannot diagnose ADHD, anxiety, or any psychiatric condition. It also cannot measure IQ, creativity, or attention level.",
    guideBetaDesc: "Beta waves are associated with active thinking, focused attention, and alert states. They typically appear in frontal and central regions.",
    guideBetaTitle: "Beta Waves (β)",
    guideBetaWhat: "β waves range 13–30 Hz, low amplitude (5–20 μV), mainly frontal/central. They increase with eyes open, mental activity, or anxiety. Sedatives can increase beta activity.",
    guideBetaWhy: "Beta reflects cortical active processing. Regional beta activity differences can inform cognitive studies, but EMG artifacts also produce beta-range signals.",
    guideChannelsCannotTell: "Low channel count (<8) EEG cannot perform reliable source localization or connectivity analysis. Channel count alone does not determine data quality.",
    guideChannelsDesc: "The number of EEG channels determines spatial resolution. The standard 10-20 system defines electrode placement, the international standard for EEG recording.",
    guideChannelsTitle: "EEG Channels & 10-20 System",
    guideChannelsWhat: "The 10-20 system divides the scalp by 10% and 20% intervals. Electrodes are named by letter (F=Frontal, C=Central, P=Parietal, O=Occipital, T=Temporal) + number (odd=left, even=right). Clinical: 19-21 channels; Research: 32/64/128 channels.",
    guideChannelsWhy: "Channel count affects source localization accuracy. More electrodes = denser spatial sampling, but collection time, comfort, and cost increase. Missing channels severely impact analysis.",
    guideDeltaCannotTell: "Delta alone cannot diagnose brain tumors, injury, or any specific disease. Physicians need MRI, CT, and other tests for comprehensive evaluation.",
    guideDeltaDesc: "Delta waves are the slowest brain waves, primarily occurring during deep sleep. Delta in awake adults is typically abnormal.",
    guideDeltaTitle: "Delta Waves (δ)",
    guideDeltaWhat: "δ waves range 0.5–4 Hz, high amplitude (100–200 μV), widely distributed. Hallmark of NREM stage 3 (slow wave sleep). Focal delta in awake state may suggest structural brain lesions.",
    guideDeltaWhy: "Delta is crucial for evaluating sleep quality and depth. Slow wave activity during deep sleep is believed essential for memory consolidation and brain restoration.",
    guideDisclaimer: "Disclaimer: All knowledge cards above are for EEG educational purposes only. They do not constitute medical advice, diagnosis, or treatment recommendations. EEG data alone cannot diagnose any disease. For health concerns, consult a qualified physician.",
    guideEmptyState: "No matching knowledge cards found",
    guideNoiseCannotTell: "There is no absolutely 'clean' EEG. All EEG contains some noise. SNR values cannot be directly compared across devices.",
    guideNoiseDesc: "EEG inherently has a low signal-to-noise ratio. Environmental EM noise, electrode impedance, and physiological artifacts all affect data quality.",
    guideNoiseTitle: "Signal Noise & SNR",
    guideNoiseWhat: "SNR = signal power / noise power. EEG amplitude typically 10–100 μV. Noise sources include: 50/60 Hz power line, electrode-skin contact noise, subject movement, etc.",
    guideNoiseWhy: "Low SNR makes frequency, ERP, and connectivity analyses unreliable. Ways to improve SNR: low impedance (<5 kΩ), shielded environment, bandpass filtering (0.5–40 Hz), signal averaging.",
    guidePsdCannotTell: "PSD cannot detect transient events (spikes, ERPs). PSD is an average measure and cannot reflect temporal dynamics of the signal.",
    guidePsdDesc: "PSD is the core tool for EEG frequency-domain analysis, quantifying power distribution across frequencies.",
    guidePsdTitle: "Power Spectral Density (PSD)",
    guidePsdWhat: "PSD transforms time-domain EEG to frequency domain via Fourier transform (commonly Welch method). Units: μV²/Hz or dB. Widely used in sleep and cognitive research.",
    guidePsdWhy: "PSD enables quantification of band energy (bandpower), identification of dominant rhythms, comparison of spectral differences across conditions/groups. Foundation for connectivity, time-frequency analyses.",
    guideSamplingCannotTell: "High sampling rate cannot compensate for poor signal quality. Sampling >1000 Hz provides no additional benefit for routine EEG analysis.",
    guideSamplingDesc: "Sampling rate determines the temporal resolution of EEG. According to Nyquist theorem, it must be at least 2× the highest frequency of interest.",
    guideSamplingTitle: "Sampling Rate",
    guideSamplingWhat: "Sampling rate is measured in Hz, common values: 128/256/500/1000 Hz. 250 Hz means 250 data points per second. Nyquist frequency = sampling rate / 2, the highest analyzable frequency.",
    guideSamplingWhy: "Insufficient sampling causes aliasing, where high frequencies masquerade as low frequencies. For standard EEG (<40 Hz), 128 Hz is usually sufficient, but studying gamma (>50 Hz) requires ≥250 Hz.",
    guideSearchPlaceholder: "Search knowledge cards...",
    guideAlphaFrequency: "8 – 12 Hz",
    guideAlphaRanges: "8 – 12 Hz, occipital dominant",
    guideBetaFrequency: "12 – 30 Hz",
    guideBetaRanges: "12 – 30 Hz, frontocentral dominant",
    guideThetaFrequency: "4 – 8 Hz",
    guideThetaRanges: "4 – 8 Hz, frontotemporal dominant",
    guideDeltaFrequency: "0.5 – 4 Hz",
