    guideChannelsRanges: "Standard: 19–21 (clinical), 32–256 (research)",
    guideSamplingRanges: "Clinical: 128–256 Hz; Research: 250–1000+ Hz",
    guidePsdRanges: "Typical resolution: 0.5–2 Hz bins, analyzed 0.5–40 Hz",
    guideBandpowerRanges: "Delta: 0.5–4 Hz; Theta: 4–8 Hz; Alpha: 8–12 Hz; Beta: 12–30 Hz",
    guidePageSubtitle: "Interactive EEG Knowledge Cards · Click to expand",
    guideThetaCannotTell: "Theta cannot diagnose ADHD (despite hypotheses about theta/beta ratio), judge meditation depth, memory quality, or brain disease.",
    guideThetaDesc: "Theta waves are associated with meditation, light sleep, and memory encoding. More common in children/adolescents; excessive theta in awake adults may indicate abnormality.",
    guideThetaTitle: "Theta Waves (θ)",
    guideThetaWhat: "θ waves range 4–8 Hz, medium to high amplitude (20–100 μV), distributed in frontal and temporal regions. Prominent during sleep transition and REM sleep.",
    guideThetaWhy: "Theta participates in memory consolidation and spatial navigation. Hippocampal theta rhythm plays a key role in learning. Clinically, diffuse theta may be seen in certain encephalopathies, requiring physician evaluation.",

