    guideSubtitle: "El EEG registra la actividad eléctrica de tu cerebro. Aquí hay algunos conceptos básicos para ayudarte a entender qué pueden y no pueden decirte los datos EEG.",
    brainWaveTypes: "Tipos Básicos de Ondas Cerebrales",
    alphaDesc: "Las ondas Alfa son la actividad cerebral dominante cuando estás relajado con los ojos cerrados. Típicamente aparecen en regiones posteriores y señalan un estado de \"reposo\".",
    alphaDetail1: "Las ondas Alfa aumentan cuando cierras los ojos y te relajas",
    alphaDetail2: "El Alfa se bloquea cuando abres los ojos o enfocas la atención",
    alphaDetail3: "La intensidad de Alfa refleja si tu cerebro está en un estado relajado",
    betaDesc: "Las ondas Beta están asociadas con el pensamiento activo, la concentración, la resolución de problemas y la ansiedad. Beta aumenta cuando estás pensando, calculando o sintiéndote tenso.",
