    thetaDesc: "Las ondas Theta típicamente aparecen durante relajación profunda, meditación, sueño ligero o pensamiento creativo. Más comunes en niños; en adultos, Theta puede indicar somnolencia o estados especiales.",
    thetaDetail1: "Theta aparece en etapas tempranas del sueño",
