    guideTitle: "Base de Connaissances EEG",
    guideSubtitle: "L'EEG enregistre l'activité électrique de votre cerveau. Voici quelques bases pour vous aider à comprendre ce que les données EEG peuvent et ne peuvent pas vous dire.",
    brainWaveTypes: "Types de Base des Ondes Cérébrales",
    alphaDesc: "Les ondes Alpha sont l'activité cérébrale dominante lorsque vous êtes relaxé les yeux fermés. Elles apparaissent typiquement dans les régions postérieures et signalent un état de \"repos\".",
    alphaDetail1: "Les ondes Alpha augmentent lorsque vous fermez les yeux et vous relaxez",
    alphaDetail2: "L'Alpha se bloque lorsque vous ouvrez les yeux ou concentrez votre attention",
    alphaDetail3: "L'intensité Alpha reflète si votre cerveau est dans un état relaxé",
    betaDesc: "Les ondes Beta sont associées à la pensée active, la concentration, la résolution de problèmes et l'anxiété. Beta augmente lorsque vous pensez, calculez ou vous sentez tendu.",
    betaDetail1: "Beta est plus proéminent dans les régions frontales",
    betaDetail2: "Augmente avec une activité mentale de haute intensité",
    betaDetail3: "Beta peut devenir surrenchérie dans certains états d'anxiété",
    thetaDesc: "Les ondes Theta apparaissent typiquement pendant la relaxation profonde, la méditation, le sommeil léger ou la pensée créative. Plus communes chez les enfants; chez les adultes, Theta peut indiquer la somnolence ou des états spéciaux.",
    thetaDetail1: "Theta apparaît dans les premières étapes du sommeil",
    thetaDetail2: "Les individus méditatifs et créatifs peuvent avoir plus de Theta",
    thetaDetail3: "Theta excessif peut indiquer une mauvaise attention",
    deltaDesc: "Les ondes Delta sont l'activité de fréquence la plus basse, présente principalement dans le sommeil profond. Delta à l'état de veille est habituellement anormal et peut indiquer une fonction cérébrale altérée.",
    deltaDetail1: "Delta apparaît dans le sommeil profond (étage N3)",
