    alphaPowerHelp: "Les ondes Alpha (α) sont généralement renforcées en relaxation yeux fermés, 8-13 Hz, surtout dans le lobe occipital. Une puissance alpha élevée indique une relaxation accrue.",
    betaPowerHelp: "Les ondes Beta (β) sont associées à la pensée active et à l'attention concentrée, 13-30 Hz, dans les régions frontales. Reflète l'engagement cognitif.",
    thetaPowerHelp: "Les ondes Theta (θ) apparaissent lors de somnolence légère, méditation ou récupération de mémoire, 4-8 Hz. Reliées à la créativité ou sommeil léger.",
    deltaPowerHelp: "Les ondes Delta (δ) sont des marqueurs du sommeil profond, 0.5-4 Hz, diffusées sur le cortex. Puissance delta élevée = sommeil réparateur.",
    alphaFreqHelp: "La fréquence de pic alpha est typiquement entre 9-11 Hz, variant avec l'âge et l'état cognitif. Un décalage peut indiquer des changements neurologiques.",
    betaFreqHelp: "Beta couvre une large gamme (13-30 Hz). Bêta bas (13-20 Hz) = concentration calme; bêta haut (20-30 Hz) = hypervigilance ou anxiété.",
    thetaFreqHelp: "Gamme thêta: 4-8 Hz. 4-6 Hz courant en méditation profonde; 6-8 Hz pendant la pensée créative ou le codage de la mémoire.",
    deltaFreqHelp: "Delta: 0.5-4 Hz, le rythme cérébral le plus lent. Le cerveau génère beaucoup de delta en sommeil profond, essentiel pour consolidation et récupération.",
    noiseHelp: "Niveau de bruit simule le bruit de fond et les interférences dans les signaux EEG. Dans un EEG réel, le bruit peut provenir d'un mauvais contact des électrodes, d'une activité musculaire ou d'interférences électromagnétiques.",

    artifactBlinkHelp: "Les artéfacts de clignement proviennent des mouvements oculaires, plus prononcés dans les électrodes frontales (Fp1/Fp2). Supprimés par ICA ou seuillage dans l'analyse EEG réelle.",
    artifactMuscleHelp: "Les artéfacts EMG (musculaires) sont causés par la contraction des muscles temporaux ou frontaux, 20-300+ Hz, visibles sur les électrodes temporales (T3/T4). Activité haute fréquence dense.",
    artifactPowerlineHelp: "Interférence secteur (50Hz/60Hz) par couplage électromagnétique du réseau électrique dans les signaux EEG, bruit sinusoïdal 50Hz sur tous les canaux. Filtré par filtre coupe-bande.",
