    guideTitle: "EEG-Wissensdatenbank",
    guideSubtitle: "EEG zeichnet die elektrische Aktivität Ihres Gehirns auf. Hier sind einige Grundlagen, die Ihnen helfen, zu verstehen, was EEG-Daten Ihnen sagen können und was nicht.",
    brainWaveTypes: "Grundlegende Typen von Hirnwellen",
    alphaDesc: "Alpha-Wellen sind die dominierende Hirnaktivität, wenn Sie entspannt mit geschlossenen Augen sind. Sie erscheinen typischerweise in hinteren Regionen und signalisieren einen \"Ruhe\"-Zustand.",
    alphaDetail1: "Alpha-Wellen nehmen zu, wenn Sie die Augen schließen und sich entspannen",
    alphaDetail2: "Alpha blockiert, wenn Sie die Augen öffnen oder die Aufmerksamkeit fokussieren",
    alphaDetail3: "Die Alpha-Intensität spiegelt wider, ob Ihr Gehirn sich in einem entspannten Zustand befindet",
    betaDesc: "Beta-Wellen sind mit aktivem Denken, Konzentration, Problemlösung und Angst verbunden. Beta nimmt zu, wenn Sie denken, rechnen oder sich angespannt fühlen.",
    betaDetail1: "Beta ist am prominentesten in frontalen Regionen",
    betaDetail2: "Nimmt mit hochintensiver mentaler Aktivität zu",
    betaDetail3: "Beta kann in einigen Angstzuständen überaktiv werden",
    thetaDesc: "Theta-Wellen erscheinen typischerweise während tiefer Entspannung, Meditation, leichtem Schlaf oder kreativem Denken. Häufiger bei Kindern; bei Erwachsenen kann Theta Schläfrigkeit oder besondere Zustände anzeigen.",
    thetaDetail1: "Theta erscheint in frühen Schlafstadien",
    thetaDetail2: "Meditative und kreative Personen können mehr Theta haben",
    thetaDetail3: "Exzessives Theta kann auf schlechte Aufmerksamkeit hinweisen",
    deltaDesc: "Delta-Wellen sind die niedrigste Frequenzaktivität, hauptsächlich in tiefem Schlaf vorhanden. Delta im Wachzustand ist normalerweise anomal und kann auf beeinträchtigte Hirnfunktion hinweisen.",
    deltaDetail1: "Delta erscheint in tiefem Schlaf (N3-Stadium)",
