    tagMemory: "Gedächtnis",
    tagThalamus: "Thalamus",
      guideAlphaCannotTell: "Alpha kann keine Krankheit, Intelligenz, Emotionszustand oder Persönlichkeit diagnostizieren. Eine reduzierte Alpha-Aktivität kann einfach durch geöffnete Augen, Anspannung oder Aufmerksamkeit verursacht werden.",
    guideAlphaDesc: "Alpha-Wellen sind die häufigsten rhythmischen Aktivitäten im EEG und treten besonders bei geschlossenen Augen auf in einem entspannten aber wachem Zustand. Sie sind eines der klassischsten Findungen in EEG-Forschung.",
    guideAlphaPattern: "Typische Alpha-Rhythmen erscheinen sinusoid und sind am deutlichsten in occipitalen Leitern (z.B. O1, O2) zu sehen, wobei sie auf dem EEG regelmäßige ~10-Hertz-Oszillationen zeigen.",
    guideAlphaTitle: "Alpha-Wellen (α)",
    guideAlphaWhat: "Alpha-Wellen haben eine Frequenz von 8–13 Hz, einen Amplitudenwert von 20–100 μV und verteilen sich vor allem im Occipitalloch. Sie vermindern sich schnell beim Öffnen der Augen, was als Alpha-Blockade bekannt ist.",
    guideAlphaWhy: "Alpha ist ein wichtiger Indikator für einen kortexbezogenen 'Idle'-Zustand. Die Abwesenheit oder Abnormität von Alpha kann eine Kortexfunktionstauheit anzeigen, aber Alpha allein kann keine Krankheit diagnostizieren.",
    guideArtifactsCannotTell: "Die Entfernung von Artfakten kann nicht alle Rauschen eliminieren und kontaminierte Hirnsignale perfekt wiederherstellen. Übermäßig starke Entfernung kann echte EEG-Signale verlieren.",
    guideArtifactsDesc: "Artfakte sind nicht-hirnbezogene Signale im EEG, die eine sorgfältige Analyse stark beeinträchtigen, wenn sie nicht erkannt und entfernt werden.",
    guideArtifactsTitle: "EEG-Artfakte",
    guideArtifactsWhat: "Häufige Artfakte: Augenblinzeln (EOG, bis zu 200 μV), Muskelaufwand (EMG, >20 Hz), Stromkreisinterferenz (50/60 Hz), Elektrodenbewegung, Schweiß. Jedes hat eine charakteristische Wellenform und Frequenzstruktur.",
    guideArtifactsWhy: "Die Identifikation von Artfakten ist der erste Schritt in der EEG-Analyse. Ohne die Behandlung von Artfakten können Frequenzanalyse, Zusammenhänge und alle weiteren Analysen falsche Schlussfolgerungen produzieren. ICA ist die häufigste automatisierte Entfernungsmethode.",
    guideBandpowerCannotTell: "Bandpower kann keine Krankheit diagnostizieren. Es gibt große individuelle Variationen (Alter, Geschlecht, Genetik, Zustand), und es gibt keine absoluten 'Normalwerte'.",
    guideBandpowerDesc: "Bandpower fasst PSD-Ergebnisse in sinnvolle Bandwerte zusammen, einer der häufigsten EEG-Metriken.",
    guideBandpowerTitle: "Bandpower",
    guideBandpowerWhat: "Energiedatum pro Band aus PSD extrahieren: Delta (0,5–4 Hz), Theta (4–8 Hz), Alpha (8–13 Hz), Beta (13–30 Hz). Ausgedrückt als absolute Leistung (μV²) oder relative Leistung (%)",
    guideBandpowerWhy: "Bandpower bildet die Grundlage für EEG-Biomarker-Forschung. Zum Beispiel wird die Alpha/Theta-Verhältnis zur Bewertung der Entspannung verwendet, und die Theta/Beta-Verhältnis wurde als möglicher ADHD-Marker untersucht (aber noch nicht für klinische Diagnose genehmigt).",
    guideBetaCannotTell: "Beta kann keine ADHD, Angst oder andere psychische Erkrankungen diagnostizieren. Es kann auch nicht das IQ, die Kreativität oder den Aufmerksamkeitslevel messen.",
    guideBetaDesc: "Beta-Wellen sind mit aktivem Denken, konzentriertem Aufmerksamkeit und alerten Zuständen verbunden. Sie treten typischerweise in vorderen und zentralen Regionen auf.",
    guideBetaTitle: "Beta-Wellen (β)",
    guideBetaWhat: "Beta-Wellen liegen im Bereich von 13–30 Hz, haben eine niedrige Amplitude (5–20 μV) und sind vor allem frontal/zentral zu finden. Sie steigern sich mit geöffneten Augen, geistiger Aktivität oder Anspannung. Sedative können Beta-Aktivität erhöhen.",
    guideBetaWhy: "Beta spiegelt den kortexbezogenen aktiven Verarbeitungsprozess wider. Regionale Unterschiede in der Beta-Aktivität können kognitive Studien informieren, aber EMG-Artfakte produzieren auch Beta-Bereichssignale.",
    guideChannelsCannotTell: "Mit weniger als 8 Elektroden kann EEG keine zuverlässige Quellenlokalisierung oder Zusammenhangsanalyse durchführen. Die Anzahl der Elektroden allein bestimmt nicht die Datenqualität.",
    guideChannelsDesc: "Die Anzahl der EEG-Leitern bestimmt die räumliche Auflösung. Das Standard-10-20-System definiert die Elektrodenplatzierung und ist das internationale Standard für EEG-Aufnahmen.",
    guideChannelsTitle: "EEG-Leitern & 10-20-System",
    guideChannelsWhat: "Das 10-20-System teilt den Schädel in 10%- und 20%-Intervallen auf. Elektroden werden durch Buchstaben (F=Frontal, C=Zentrale, P=Parietale, O=Occipitale, T=Temporale) und Zahlen (ungerade=links, gerade=rechts) benannt. Klinisch: 19-21-Leitern; Forschung: 32/64/128-Leitern.",
    guideChannelsWhy: "Die Anzahl der Elektroden beeinflusst die Genauigkeit der Quellenlokalisierung. Mehr Elektroden = dichteres räumliches Abtasten, aber die Sammelzeit, Komfort und Kosten steigen. Mangelnde Elektroden beeinträchtigen die Analyse stark.",
    guideDeltaCannotTell: "Delta allein kann keine Hirntumor, Verletzung oder spezifische Erkrankungen diagnostizieren. Ärzte benötigen MRI, CT und andere Tests für eine umfassende Bewertung.",
    guideDeltaDesc: "Delta-Wellen sind die langsamen Wellen des Gehirns und treten hauptsächlich während tiefem Schlaf auf. Delta bei erwachenden Erwachsenen ist normalerweise abnorm.",
    guideDeltaTitle: "Delta-Wellen (δ)",
    eegSimulator: "EEG-Simulator",
    eegSimulatorDesc: "Parameter anpassen, um synthetische EEG-Signale zu erzeugen und verschiedene Gehirnzustände zu beobachten",

    alphaPowerHelp: "Alpha-Wellen (α) werden bei Entspannung mit geschlossenen Augen verstärkt, 8-13 Hz, am stärksten im Okzipitallappen. Höhere Alpha-Leistung bedeutet mehr Entspannung.",
    betaPowerHelp: "Beta-Wellen (β) werden mit aktivem Denken und fokussierter Aufmerksamkeit assoziiert, 13-30 Hz, in Frontallappen. Spiegelt kognitives Engagement wider.",
    thetaPowerHelp: "Theta-Wellen (θ) treten bei leichter Schläfrigkeit, Meditation oder Gedächtnisabruf auf, 4-8 Hz. Können mit Kreativität oder Leichtschlaf zusammenhängen.",
    deltaPowerHelp: "Delta-Wellen (δ) sind Marker für Tiefschlaf, 0.5-4 Hz, über die Kortex verteilt. Hohe Delta-Leistung bedeutet erholsamen Tiefschlaf.",
    alphaFreqHelp: "Alpha-Spitzenfrequenz liegt typisch zwischen 9-11 Hz, variiert mit Alter und kognitivem Zustand. Verschiebung kann neurologische Veränderungen anzeigen.",
    betaFreqHelp: "Beta umfasst einen breiten Bereich (13-30 Hz). Niedriges Beta (13-20 Hz) = ruhige Konzentration; hohes Beta (20-30 Hz) = Übererregung oder Angst.",
    thetaFreqHelp: "Theta-Bereich: 4-8 Hz. 4-6 Hz bei tiefer Meditation; 6-8 Hz bei kreativem Denken oder Gedächtniskodierung.",
    deltaFreqHelp: "Delta: 0.5-4 Hz, der langsamste Hirnrhythmus. Das Gehirn erzeugt reichlich Delta im Tiefschlaf, essenziell für Gedächtnisfestigung und Erholung.",
    noiseHelp: "Rauschpegel simuliert Hintergrundrauschen in EEG-Signalen. Reales EEG-Rauschen kann durch schlechten Elektrodenkontakt, Muskelaktivität oder elektromagnetische Störungen entstehen.",

    artifactBlinkHelp: "Blinkartefakte entstehen durch Augenbewegungen, am stärksten in frontalen Elektroden (Fp1/Fp2). In der echten EEG-Analyse mittels ICA oder Schwellenwert entfernt.",
    artifactMuscleHelp: "EMG (Muskel-)Artefakte entstehen durch temporale oder frontale Muskelkontraktion, 20-300+ Hz, sichtbar in temporalen Elektroden (T3/T4). Gekennzeichnet durch dichte Hochfrequenzaktivität.",
    artifactPowerlineHelp: "Netzstörung (50Hz/60Hz) durch elektromagnetische Einkopplung des Stromnetzes in EEG-Signale, als konsistentes 50Hz-Sinusrauschen auf allen Kanälen. Mittels Notch-Filter entfernt.",
