      guideAlphaCannotTell: "アルファはどの病気も診断することができません。知能、感情状態、または人格を判断することもできません。アルファの減少は単に目を開けている、不安、または注意が散漫な場合などに起こるだけかもしれません。",
    guideAlphaDesc: "アルファ波はEEGで最も一般的なリズミック活動であり、人間が目を閉じてリラックスしたながら覚醒した状態では目立つ。これはEEG研究において最も classicsな見出しだ。",
    guideAlphaPattern: "典型的なアルファリズムは正弦波状に現れ、特に枕葉の電極（例えばO1、O2）で最も明瞭で、EEG上では約10 Hzの定期的な振動を示します。",
    eegSimulator: "EEG シミュレーター",
    eegSimulatorDesc: "パラメータを調整して合成 EEG 信号を生成し、異なる脳状態を観察します",

    alphaPowerHelp: "α（アルファ）波はリラックスして目を閉じたときに増強され、8–13 Hz、後頭葉で最も顕著です。アルファ波のパワーが高いほどリラックス度が高いことを示します。",
    betaPowerHelp: "β（ベータ）波は能動的思考や集中した注意力と関連し、13–30 Hz、前頭葉で顕著です。ベータ波のパワーは認知活動の活発さを反映します。",
    thetaPowerHelp: "θ（シータ）波は軽い眠気、瞑想、記憶想起時に現れ、4–8 Hz。シータ波の増加は創造性や浅い睡眠に関連する可能性があります。",
    deltaPowerHelp: "δ（デルタ）波は深い睡眠の指標であり、0.5–4 Hz、大脳皮質全体に拡散します。デルタ波のパワーが高いと深い回復睡眠に入っていることを示します。",
    alphaFreqHelp: "α波のピーク周波数は通常 9–11 Hz で、年齢や認知状態によって変化します。周波数の偏移（例：8 Hz 未満）は神経学的変化を示す可能性があります。",
    betaFreqHelp: "β波は広い周波数範囲（13–30 Hz）をカバーします。低β（13–20 Hz）は落ち着いた集中、高β（20–30 Hz）は過覚醒や不安と関連します。",
    thetaFreqHelp: "θ波の周波数範囲は4–8 Hz。4–6 Hz は深い瞑想で一般的で、6–8 Hz は創造的思考や記憶符号化時に現れます。",
    deltaFreqHelp: "δ波は 0.5–4 Hz で最も遅い脳波リズムです。脳は深い睡眠中に大量のデルタ波を生成し、記憶の固定と身体の回復に不可欠です。",
    noiseHelp: "ノイズレベルは EEG 信号の背景ノイズと干渉をシミュレートします。実際の EEG では、電極接触不良、筋活動、環境電磁干渉などがノイズ源となります。",

    artifactBlinkHelp: "瞬目アーチファクトは眼球運動（まばたき時の角膜-網膜電位変化）により生じ、前頭葉電極（Fp1/Fp2）で最も顕著です。実際のEEG解析ではICAや閾値法で除去されます。",
    artifactMuscleHelp: "筋電図アーチファクト（EMG）は側頭筋や前頭筋の収縮により生じ、広い周波数範囲（20–300+ Hz）を持ち、側頭葉電極（T3/T4）で最も顕著です。高密度の高周波活動が特徴です。",
    artifactPowerlineHelp: "電源干渉（50Hz/60Hz）は電力系統の電磁界がEEG信号に結合することで発生し、全チャンネルで一貫した50Hz正弦波ノイズとして現れます。実際にはノッチフィルタで除去します。",
