    eegSimulator: "EEG 시뮬레이터",
    eegSimulatorDesc: "매개변수를 조정하여 합성 EEG 신호를 생성하고 다양한 뇌 상태를 관찰합니다",

    alphaPowerHelp: "α (알파) 파는 편안하게 눈을 감았을 때 증가하며, 8–13 Hz, 후두엽에서 가장 두드러집니다. 알파파 출력이 높을수록 이완 정도가 높음을 나타냅니다.",
    betaPowerHelp: "β (베타) 파는 능동적 사고와 집중된 주의력과 관련되며, 13–30 Hz, 전두엽에서 두드러집니다. 베타파 출력은 인지 활동 수준을 반영합니다.",
    thetaPowerHelp: "θ (세타) 파는 가벼운 졸음, 명상 또는 기억 회상 시 나타나며, 4–8 Hz입니다. 세타파 출력 증가는 창의성이나 얕은 수면과 관련될 수 있습니다.",
    deltaPowerHelp: "δ (델타) 파는 깊은 수면의 지표이며, 0.5–4 Hz, 대뇌피질 전반에 확산됩니다. 델타파 출력이 높으면 깊은 회복 수면에 들어간 것을 의미합니다.",
    alphaFreqHelp: "알파파의 피크 주파수는 일반적으로 9–11 Hz 사이이며, 나이와 인지 상태에 따라 변합니다. 주파수 편이(예: 8 Hz 미만)는 신경학적 변화를 암시할 수 있습니다.",
    betaFreqHelp: "베타파는 넓은 주파수 범위(13–30 Hz)를 포괄합니다. 낮은 베타(13–20 Hz)는 차분한 집중, 높은 베타(20–30 Hz)는 과도한 경계나 불안과 관련됩니다.",
    thetaFreqHelp: "세타파 주파수 범위는 4–8 Hz입니다. 4–6 Hz는 깊은 명상에서 흔하며, 6–8 Hz는 창의적 사고나 기억 부호화 시 나타납니다.",
    deltaFreqHelp: "델타파(0.5–4 Hz)는 가장 느린 뇌파 리듬입니다. 뇌는 깊은 수면 중에 풍부한 델타파를 생성하며, 이는 기억 강화와 신체 회복에 필수적입니다.",
    noiseHelp: "노이즈 수준은 EEG 신호의 배경 노이즈와 간섭을 시뮬레이션합니다. 실제 EEG에서 노이즈는 전극 접촉 불량, 근육 활동 또는 전자기 간섭에서 발생할 수 있습니다.",

    artifactBlinkHelp: "눈 깜빡임 인공물은 안구 운동(깜빡일 때 각막-망막 전위 변화)으로 인해 발생하며, 전두엽 전극(Fp1/Fp2)에서 가장 두드러집니다. 실제 EEG 분석에서는 ICA 또는 임계값 방법으로 제거됩니다.",
    artifactMuscleHelp: "근전도(EMG) 인공물은 측두근 또는 전두근 수축으로 인해 발생하며, 넓은 주파수 범위(20–300+ Hz)를 가지며 측두엽 전극(T3/T4)에서 가장 두드러집니다. 고밀도 고주파 활동이 특징입니다.",
    artifactPowerlineHelp: "전원 간섭(50Hz/60Hz)은 전력 계통의 전자기장이 EEG 신호에 결합되어 발생하며, 모든 채널에서 일관된 50Hz 사인파 노이즈로 나타납니다. 실제로 노치 필터를 통해 제거됩니다.",
